// app/logo.jsx — Fightlytics glove mark + wordmark lockup
const GLOVE_PAD = 'M38 18h32c8 0 14 6 14 14v24c0 8-6 14-14 14H38c-8 0-14-6-14-14V32c0-8 6-14 14-14z';
const GLOVE_THUMB = 'M24 34h-8c-6 0-11 5-11 11 0 6 5 10 11 10h8z';
const GLOVE_CUFF = 'M26 70h56v10c0 4-4 8-8 8H34c-4 0-8-4-8-8z';
const GLOVE_STRAP_A = 'M38 76h32';
const GLOVE_STRAP_B = 'M38 83h32';
const GLOVE_GROOVES = ['M40 24v18', 'M54 24v18', 'M68 24v18'];

function GloveMark({ size = 34, mono = false }) {
  const cyan = mono ? 'currentColor' : '#ff4d1c';
  const fill = mono ? 'none' : 'rgba(255,77,28,.12)';
  const w = size < 36 ? 6.5 : 5.5;
  return (
    <svg width={size} height={size} viewBox="0 0 100 100" aria-hidden="true" style={{ flex: 'none', display: 'block' }}>
      <path d={GLOVE_CUFF} fill={mono ? 'none' : 'rgba(255,77,28,.06)'} stroke={cyan} strokeWidth={w} strokeLinejoin="round" />
      <path d={GLOVE_THUMB} fill={fill} stroke={cyan} strokeWidth={w} strokeLinejoin="round" />
      <path d={GLOVE_PAD} fill={fill} stroke={cyan} strokeWidth={w} strokeLinejoin="round" />
      {GLOVE_GROOVES.map((d, i) => (
        <path key={i} d={d} stroke={cyan} strokeWidth={size < 36 ? 5.5 : 5} strokeLinecap="round" />
      ))}
      <path d={GLOVE_STRAP_A} stroke={cyan} strokeWidth="4.5" strokeLinecap="round" />
      <path d={GLOVE_STRAP_B} stroke={cyan} strokeWidth="4.5" strokeLinecap="round" />
    </svg>
  );
}

// small single-ink glove for eyebrows / section labels — inherits currentColor
function GloveGlyph({ size = 14 }) {
  return (
    <svg width={size} height={size} viewBox="0 0 100 100" aria-hidden="true" style={{ flex: 'none', display: 'block' }}>
      <path d={GLOVE_CUFF} fill="none" stroke="currentColor" strokeWidth="7" strokeLinejoin="round" />
      <path d={GLOVE_THUMB} fill="none" stroke="currentColor" strokeWidth="7" strokeLinejoin="round" />
      <path d={GLOVE_PAD} fill="none" stroke="currentColor" strokeWidth="7" strokeLinejoin="round" />
      {GLOVE_GROOVES.map((d, i) => (
        <path key={i} d={d} stroke="currentColor" strokeWidth="6" strokeLinecap="round" />
      ))}
    </svg>
  );
}

// oversized outline glove used as a background motif
function GloveWatermark({ className = '', style = null }) {
  return (
    <svg className={'glove-wm ' + className} style={style} viewBox="0 0 100 100" aria-hidden="true">
      <path d={GLOVE_CUFF} fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinejoin="round" />
      <path d={GLOVE_THUMB} fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinejoin="round" />
      <path d={GLOVE_PAD} fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinejoin="round" />
      {GLOVE_GROOVES.map((d, i) => (
        <path key={i} d={d} stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
      ))}
      <path d={GLOVE_STRAP_A} stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
      <path d={GLOVE_STRAP_B} stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
    </svg>
  );
}

function LogoStack({ size = 64, wordSize = 34, sub = null }) {
  return (
    <div className="brand stack">
      <GloveMark size={size} />
      <div className="brand-word" style={{ fontSize: wordSize }}>fightlytics</div>
      {sub && <div className="brand-sub">{sub}</div>}
    </div>
  );
}

function LogoLockup({ size = 34, wordSize = 26, sub = null }) {
  return (
    <div className="brand">
      <GloveMark size={size} />
      <div>
        <div className="brand-word" style={{ fontSize: wordSize }}>fightlytics</div>
        {sub && <div className="brand-sub">{sub}</div>}
      </div>
    </div>
  );
}

Object.assign(window, { GloveMark, GloveGlyph, GloveWatermark, LogoLockup, LogoStack });
// app/mockup.jsx — recreated Fight.AI analysis player + faux-live event feed
const { useState, useEffect, useRef } = React;

// Event color system from the design system
const EV = {
  strike:  { color: '#ff4d1c', icon: 'bolt' },
  kick:    { color: '#ff4d1c', icon: 'sports_martial_arts' },
  block:   { color: '#94a3b8', icon: 'shield' },
  grapple: { color: '#ff7043', icon: 'sports_kabaddi' },
  round:   { color: '#a3c900', icon: 'timer' },
  state:   { color: '#64748b', icon: 'radio_button_checked' },
};

// Scripted event stream (cycles). Frame numbers tick up to feel live.
const STREAM = [
  { t: 'kick',    f: 5256, d: '<b>fighter_blue</b> threw a low_kick' },
  { t: 'kick',    f: 5256, d: '<b>fighter_red</b> threw a low_kick' },
  { t: 'grapple', f: 5257, d: 'State → <b>GRAPPLING</b> · takedown by fighter_red' },
  { t: 'state',   f: 5493, d: 'Fight state changed to <b>STRIKING</b>' },
  { t: 'strike',  f: 5821, d: '<b>fighter_blue</b> landed a jab' },
  { t: 'block',   f: 6002, d: '<b>fighter_red</b> checked a leg kick' },
  { t: 'strike',  f: 6340, d: '<b>fighter_red</b> landed a right_hand' },
  { t: 'strike',  f: 6712, d: '<b>fighter_blue</b> landed a hook' },
  { t: 'round',   f: 7829, d: '<b>Round 1</b> ended' },
  { t: 'grapple', f: 8104, d: 'clinch broken by <b>fighter_blue</b>' },
  { t: 'round',   f: 9995, d: '<b>Round 2</b> started' },
];

function EventRow({ ev }) {
  const meta = EV[ev.t];
  return (
    <div className="ev" style={{ '--ev-color': meta.color }} key={ev.uid}>
      <div className="badge"><span className="material-symbols-outlined">{meta.icon}</span></div>
      <div style={{ minWidth: 0 }}>
        <div className="frame">Frame {ev.f}</div>
        <div className="desc" dangerouslySetInnerHTML={{ __html: ev.d }} />
      </div>
    </div>
  );
}

function AnalysisMockup({ tickerSpeed = 2000, live = true }) {
  const [rows, setRows] = useState(() =>
    [2, 1, 0].map((i) => ({ ...STREAM[i], uid: 'init' + i }))
  );
  const idx = useRef(3);
  const uid = useRef(100);

  useEffect(() => {
    if (!live) return;
    const id = setInterval(() => {
      const next = STREAM[idx.current % STREAM.length];
      idx.current += 1;
      uid.current += 1;
      setRows((r) => [{ ...next, uid: uid.current }, ...r].slice(0, 5));
    }, tickerSpeed);
    return () => clearInterval(id);
  }, [tickerSpeed, live]);

  return (
    <div className="mockup">
      <div className="mockup-bar">
        <div className="dotrow"><i style={{ background: '#ff5f57' }} /><i style={{ background: '#febc2e' }} /><i style={{ background: '#28c840' }} /></div>
        <span className="mockup-title">fightlytics — analysis player</span>
        <span className="mockup-badge"><span style={{ width: 5, height: 5, borderRadius: 9, background: '#ff4d1c', display: 'inline-block', boxShadow: '0 0 6px #ff4d1c' }} />Processing</span>
      </div>

      <div className="mockup-body">
        {/* video pane */}
        <div className="video-pane">
          <div className="video-placeholder"><div className="cage-floor" /></div>
          <div className="scanline" />

          <div className="hud">
            <span className="rec" />
            <span className="txt">DETECTING · 25 FPS</span>
          </div>

          {/* fighter overlay boxes */}
          <div className="fbox red" style={{ left: '14%', top: '24%', width: '24%', height: '58%' }}>
            <span className="tag">FIGHTER_RED</span>
            <span className="conf">0.98</span>
          </div>
          <div className="fbox blue" style={{ right: '16%', top: '20%', width: '25%', height: '62%' }}>
            <span className="tag">FIGHTER_BLUE</span>
            <span className="conf">0.97</span>
          </div>

          <div className="scorestrip">
            <span className="name">BATUR</span>
            <span className="clock">R2 · 04:49</span>
            <span className="name">STAMATOVIC</span>
          </div>
        </div>

        {/* side panel */}
        <div className="side">
          <div className="round-block">
            <div className="lbl">Active Round</div>
            <div className="val">ROUND 2</div>
          </div>

          <div className="stat-tiles">
            <div className="stat-tile">
              <div className="k">Sig. Strikes</div>
              <div className="v cyan">14<small> /22</small></div>
            </div>
            <div className="stat-tile">
              <div className="k">Grapple</div>
              <div className="v orange">00:04</div>
            </div>
          </div>

          <div className="feed">
            <div className="feed-head">
              <span className="lbl">Event Timeline</span>
              <div className="feed-pills">
                <span className="feed-pill on">All</span>
                <span className="feed-pill">Strikes</span>
              </div>
            </div>
            <div className="feed-list">
              {rows.map((r) => <EventRow ev={r} key={r.uid} />)}
            </div>
            <div className="feed-cta">View Full Lab Report</div>
          </div>
        </div>
      </div>
    </div>
  );
}

Object.assign(window, { AnalysisMockup });
/* ============================================================
   Fight.AI — Hero, mockup & section styles
   ============================================================ */

/* ============================================================
   HERO
   ============================================================ */
.hero {
  position: relative;
  padding: 96px 0 48px;
}
.hero-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 48px;
  align-items: center;
}
@media (min-width: 1024px) {
  .hero-grid { grid-template-columns: minmax(0, 0.92fr) minmax(0, 1.08fr); gap: 56px; }
}

.hero-kicker {
  display: inline-flex; align-items: center; gap: 9px;
  padding: 7px 14px 7px 11px; border-radius: 999px;
  background: rgba(255, 77, 28, 0.07);
  border: 1px solid rgba(255, 77, 28, 0.15);
  margin-bottom: 26px;
}
.hero-kicker .eyebrow { color: rgba(255,77,28,0.85); }

.hero h1 {
  margin: 0;
  font-weight: 800;
  letter-spacing: -0.03em;
  line-height: 1.04;
  font-size: clamp(38px, 4.6vw, 58px);
  color: var(--text-primary);
}
.hero h1 .accent { color: var(--accent); }

/* HYPE direction: giant Bebas display headline */
[data-direction="hype"] .hero h1 {
