const INK = '242,241,238';
const STRIP_H = 34;             // css px reserved for the sample strip

const STRIKE_LABEL = {
  jab: 'Jab', cross: 'Cross', left_hook: 'Left hook', right_hook: 'Right hook',
  left_uppercut: 'Left uppercut', right_uppercut: 'Right uppercut',
