    const q = b[i];
    const x1 = Math.min(p.box[0], q.box[0]), y1 = Math.min(p.box[1], q.box[1]);
    const x2 = Math.max(p.box[2], q.box[2]), y2 = Math.max(p.box[3], q.box[3]);
