.nav-links a { font-size: 14px; font-weight: 500; color: var(--mute); text-decoration: none; transition: color 0.2s; }
.nav-links a:hover { color: var(--ink); }

/* ---------- story: hero + pipeline steps beside the pinned replay ---------- */
.story { max-width: var(--maxw); margin: 0 auto; padding: 0 32px; display: grid; grid-template-columns: minmax(0, 5fr) minmax(0, 7fr); column-gap: clamp(32px, 4.5vw, 80px); }
.hero { min-height: calc(100dvh - var(--nav-h)); display: flex; flex-direction: column; justify-content: center; gap: 26px; padding: 40px 0 56px; }
.hero-ctas { display: flex; align-items: center; gap: 28px; flex-wrap: wrap; margin-top: 6px; }
.hero > * { animation: rise 0.9s var(--ease) both; }
.hero > :nth-child(2) { animation-delay: 0.08s; }
.hero > :nth-child(3) { animation-delay: 0.16s; }
@keyframes rise { from { opacity: 0; transform: translateY(18px); } }

.step { min-height: 92dvh; display: flex; flex-direction: column; justify-content: center; gap: 18px; padding: 40px 0; }
.step:last-child { min-height: calc(100dvh - var(--nav-h)); }
.step .h3 { max-width: 15ch; }
.step-note { margin: 4px 0 0; font-size: 15px; color: var(--mute); max-width: 40ch; }
.chips, .vocab > div { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.vocab { display: flex; flex-direction: column; gap: 10px; margin-top: 4px; }
.vocab-k { width: 58px; font-size: 13px; color: var(--mute); }
.chip { font: 500 13px/1 'JetBrains Mono', monospace; padding: 7px 10px; border-radius: var(--r-ctl); border: 1px solid var(--line-2); color: var(--ink); }
.chip.c0, .chip.c1 { display: inline-flex; align-items: center; gap: 8px; }
