.chip.c1::before { background: var(--blue); }

.stage { grid-column: 2; grid-row: 1 / span 10; position: sticky; top: var(--nav-h); height: calc(100dvh - var(--nav-h)); align-self: start; display: flex; align-items: center; }
.stage-in { width: 100%; display: flex; flex-direction: column; gap: 12px; }
.stage-cap { margin: 0; font-size: 13px; line-height: 1.5; color: var(--mute); }
.stage-panel { border-radius: var(--r-panel); background: var(--panel); border: 1px solid var(--line); box-shadow: 0 30px 80px -40px rgba(0, 0, 0, 0.9), inset 0 1px 0 rgba(255, 255, 255, 0.04); overflow: hidden; }
.stage-hud { display: flex; align-items: center; gap: 16px; padding: 10px 10px 10px 16px; border-bottom: 1px solid var(--line); }
.stage-layers { list-style: none; margin: 0; padding: 0; display: flex; gap: 14px; font: 500 12px/1 'JetBrains Mono', monospace; }
.stage-layers li { color: rgba(242, 241, 238, 0.32); transition: color 0.3s; }
.stage-layers li.on { color: var(--ink); }
.stage-frame { margin-left: auto; font-size: 12px; color: var(--mute); }
.stage-frame b { display: inline-block; min-width: 5ch; color: var(--ink); font-weight: 500; }
