.sec { padding: clamp(96px, 12vw, 168px) 0 clamp(104px, 13vw, 184px); }
.sec-head { display: flex; flex-direction: column; gap: 18px; margin-bottom: 48px; }
.sec-head .body { max-width: 58ch; }

/* whole-fight timeline */
.fight { display: flex; flex-direction: column; gap: 20px; }
.fight-line-wrap { border-radius: var(--r-panel); background: var(--panel); border: 1px solid var(--line); padding: 34px 20px 14px; }
.fight-line { position: relative; height: 200px; cursor: crosshair; }
.fl-round { position: absolute; top: 0; bottom: 0; border-radius: 4px; background: rgba(255, 255, 255, 0.025); transition: background 0.3s; }
.fl-round.on { background: rgba(255, 255, 255, 0.05); }
.fl-round span { position: absolute; top: -24px; left: 0; font-size: 12px; color: var(--mute); }
.fl-mid { position: absolute; left: 0; right: 0; top: 50%; height: 1px; background: var(--line-2); }
.fl-tick { position: absolute; width: 2px; margin-left: -1px; border-radius: 1px; opacity: 0.85; transition: opacity 0.3s; }
.fl-tick.c0 { bottom: 50%; background: var(--red); }
.fl-tick.c1 { top: 50%; background: var(--blue); }
.fl-tick.off { opacity: 0.12; }
.fl-tick.hot { opacity: 1; width: 4px; margin-left: -2px; }
.fl-tip { position: absolute; top: 50%; transform: translate(10px, -50%); z-index: 1; pointer-events: none; display: flex; flex-direction: column; gap: 4px; padding: 10px 12px; border-radius: 8px; background: var(--panel-2); border: 1px solid var(--line-2); font-size: 14px; color: var(--ink); white-space: nowrap; text-transform: capitalize; box-shadow: 0 12px 32px -12px rgba(0, 0, 0, 0.8); }
.fl-tip.flip { transform: translate(calc(-100% - 10px), -50%); }
.fl-tip b.c0 { color: var(--red); } .fl-tip b.c1 { color: var(--blue); }
.fl-tip .mono { font-size: 12px; color: var(--mute); text-transform: none; }
.fl-axis { display: flex; justify-content: space-between; margin-top: 10px; font-size: 12px; color: var(--mute); }

.fight-tape { display: grid; grid-template-columns: minmax(0, 4fr) minmax(0, 7fr); gap: 20px; }
.tape-head { display: flex; flex-direction: column; justify-content: space-between; gap: 28px; padding: 24px; border-radius: var(--r-panel); background: var(--panel); border: 1px solid var(--line); }
.tape-tabs { display: flex; flex-wrap: wrap; gap: 6px; }
.tape-tabs button { height: 34px; padding: 0 12px; border-radius: var(--r-ctl); border: 1px solid var(--line); background: transparent; color: var(--mute); font: 500 14px 'Archivo', sans-serif; cursor: pointer; transition: color 0.2s, border-color 0.2s, background 0.2s; }
.tape-tabs button:hover { color: var(--ink); }
