.tape-row .k { text-align: center; font-size: 14.5px; font-weight: 600; color: var(--ink-2); }
.tape-row .bar { display: flex; height: 10px; }
.tape-row .bar.l { justify-content: flex-end; }
.tape-row .bar i { display: block; height: 100%; border-radius: 2px; transition: width 0.5s var(--ease); }
.tape-row .bar i.c0 { background: var(--red); }
.tape-row .bar i.c1 { background: var(--blue); }
.fight-key { display: flex; flex-wrap: wrap; gap: 24px; margin: 0; font-size: 12.5px; color: var(--mute); }
.fight-key span { display: inline-flex; align-items: center; gap: 8px; }
