.method-h { position: sticky; top: calc(var(--nav-h) + 48px); max-width: 13ch; }
.method-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: clamp(40px, 5vw, 72px); }
.method-list li { display: flex; flex-direction: column; gap: 10px; }
.method-k { font: 800 clamp(44px, 4.6vw, 68px)/0.9 'Archivo', sans-serif; font-stretch: 68%; color: var(--ink); letter-spacing: -0.01em; }

