:root {
  --bg: #0b0b0c;
  --panel: #0f1012;
  --panel-2: #141518;
  --line: rgba(255, 255, 255, 0.09);
  --line-2: rgba(255, 255, 255, 0.16);
  --ink: #f2f1ee;
  --ink-2: #c9c7c1;
  --mute: #8f8d87;
  --accent: #ff4d1c;
  --accent-hover: #ff6a40;
  --accent-on: #190500;
  --red: #ef4444;
  --blue: #60a5fa;
  --nav-h: 64px;
