.stage-play:hover { background: rgba(255, 255, 255, 0.06); }
.stage-play .material-symbols-outlined { font-size: 20px; }
.stage-canvas { position: relative; height: clamp(260px, min(46vh, 34vw), 520px); background: radial-gradient(ellipse 70% 60% at 50% 30%, rgba(255, 255, 255, 0.035), transparent 70%); }
.stage-canvas canvas { display: block; width: 100%; height: 100%; }
.stage-read { position: absolute; right: 14px; top: 12px; font-size: 12px; color: var(--ink); text-transform: uppercase; letter-spacing: 0.04em; }
.stage-log { height: 164px; border-top: 1px solid var(--line); padding: 6px; display: flex; flex-direction: column; gap: 2px; overflow: hidden; transition: opacity 0.4s; }
.mode-detect .stage-log, .mode-corners .stage-log { opacity: 0.35; }
.log-empty { padding: 10px; font-size: 14px; color: var(--mute); }
.log-row { display: grid; grid-template-columns: 6ch 52px 1fr; align-items: center; gap: 12px; width: 100%; text-align: left; padding: 8px 10px; border: 0; border-radius: var(--r-ctl); background: transparent; color: var(--ink-2); font: 500 14.5px/1.2 'Archivo', sans-serif; cursor: pointer; animation: log-in 0.45s var(--ease); transition: background 0.2s; }
.log-row:hover { background: rgba(255, 255, 255, 0.05); }
.log-row:first-of-type { color: var(--ink); }
.mode-log .log-row:first-of-type { background: rgba(255, 255, 255, 0.05); }
.log-f { font-size: 12.5px; color: var(--mute); }
.log-c { display: inline-flex; align-items: center; gap: 7px; font-size: 13px; color: var(--mute); }
.log-c::before { content: ''; width: 8px; height: 8px; border-radius: 2px; background: var(--red); }
.log-c.c1::before { background: var(--blue); }
@keyframes log-in { from { opacity: 0; transform: translateY(-8px); } }

/* ---------- sections ---------- */
.sec { padding: clamp(96px, 12vw, 168px) 0 clamp(104px, 13vw, 184px); }
.sec-head { display: flex; flex-direction: column; gap: 18px; margin-bottom: 48px; }
.sec-head .body { max-width: 58ch; }

/* whole-fight timeline */
.fight { display: flex; flex-direction: column; gap: 20px; }
.fight-line-wrap { border-radius: var(--r-panel); background: var(--panel); border: 1px solid var(--line); padding: 34px 20px 14px; }
.fight-line { position: relative; height: 200px; cursor: crosshair; }
.fl-round { position: absolute; top: 0; bottom: 0; border-radius: 4px; background: rgba(255, 255, 255, 0.025); transition: background 0.3s; }
.fl-round.on { background: rgba(255, 255, 255, 0.05); }
.fl-round span { position: absolute; top: -24px; left: 0; font-size: 12px; color: var(--mute); }
.fl-mid { position: absolute; left: 0; right: 0; top: 50%; height: 1px; background: var(--line-2); }
.fl-tick { position: absolute; width: 2px; margin-left: -1px; border-radius: 1px; opacity: 0.85; transition: opacity 0.3s; }
.fl-tick.c0 { bottom: 50%; background: var(--red); }
.fl-tick.c1 { top: 50%; background: var(--blue); }
.fl-tick.off { opacity: 0.12; }
.fl-tick.hot { opacity: 1; width: 4px; margin-left: -2px; }
.fl-tip { position: absolute; top: 50%; transform: translate(10px, -50%); z-index: 1; pointer-events: none; display: flex; flex-direction: column; gap: 4px; padding: 10px 12px; border-radius: 8px; background: var(--panel-2); border: 1px solid var(--line-2); font-size: 14px; color: var(--ink); white-space: nowrap; text-transform: capitalize; box-shadow: 0 12px 32px -12px rgba(0, 0, 0, 0.8); }
.fl-tip.flip { transform: translate(calc(-100% - 10px), -50%); }
.fl-tip b.c0 { color: var(--red); } .fl-tip b.c1 { color: var(--blue); }
.fl-tip .mono { font-size: 12px; color: var(--mute); text-transform: none; }
.fl-axis { display: flex; justify-content: space-between; margin-top: 10px; font-size: 12px; color: var(--mute); }

.fight-tape { display: grid; grid-template-columns: minmax(0, 4fr) minmax(0, 7fr); gap: 20px; }
.tape-head { display: flex; flex-direction: column; justify-content: space-between; gap: 28px; padding: 24px; border-radius: var(--r-panel); background: var(--panel); border: 1px solid var(--line); }
.tape-tabs { display: flex; flex-wrap: wrap; gap: 6px; }
.tape-tabs button { height: 34px; padding: 0 12px; border-radius: var(--r-ctl); border: 1px solid var(--line); background: transparent; color: var(--mute); font: 500 14px 'Archivo', sans-serif; cursor: pointer; transition: color 0.2s, border-color 0.2s, background 0.2s; }
.tape-tabs button:hover { color: var(--ink); }
.tape-tabs button[aria-pressed='true'] { color: var(--ink); border-color: var(--line-2); background: rgba(255, 255, 255, 0.06); }
.tape-totals { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
.tape-totals div { display: flex; flex-direction: column; gap: 4px; }
.tape-totals b { font-size: clamp(48px, 5vw, 72px); line-height: 0.9; font-weight: 500; letter-spacing: -0.04em; color: var(--ink); }
.tape-totals span { display: inline-flex; align-items: center; gap: 8px; font-size: 14px; color: var(--mute); }
.tape-totals span::before { content: ''; width: 8px; height: 8px; border-radius: 2px; background: var(--red); }
.tape-totals .c1 span::before { background: var(--blue); }
.tape-rows { display: flex; flex-direction: column; justify-content: center; gap: 12px; padding: 24px; border-radius: var(--r-panel); background: var(--panel); border: 1px solid var(--line); }
.tape-row { display: grid; grid-template-columns: 4ch 1fr 88px 1fr 4ch; align-items: center; gap: 12px; }
.tape-row .n { font-size: 14px; color: var(--ink); }
.tape-row .n:first-child { text-align: right; }
.tape-row .k { text-align: center; font-size: 14.5px; font-weight: 600; color: var(--ink-2); }
.tape-row .bar { display: flex; height: 10px; }
.tape-row .bar.l { justify-content: flex-end; }
.tape-row .bar i { display: block; height: 100%; border-radius: 2px; transition: width 0.5s var(--ease); }
.tape-row .bar i.c0 { background: var(--red); }
.tape-row .bar i.c1 { background: var(--blue); }
.fight-key { display: flex; flex-wrap: wrap; gap: 24px; margin: 0; font-size: 12.5px; color: var(--mute); }
.fight-key span { display: inline-flex; align-items: center; gap: 8px; }
.fight-key .k0::before, .fight-key .k1::before { content: ''; width: 8px; height: 8px; border-radius: 2px; background: var(--red); }
.fight-key .k1::before { background: var(--blue); }

/* method */
.method { border-top: 1px solid var(--line); }
.method-grid { display: grid; grid-template-columns: minmax(0, 6fr) minmax(0, 6fr); gap: clamp(40px, 6vw, 120px); align-items: start; }
.method-h { position: sticky; top: calc(var(--nav-h) + 48px); max-width: 13ch; }
.method-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: clamp(40px, 5vw, 72px); }
.method-list li { display: flex; flex-direction: column; gap: 10px; }
.method-k { font: 800 clamp(44px, 4.6vw, 68px)/0.9 'Archivo', sans-serif; font-stretch: 68%; color: var(--ink); letter-spacing: -0.01em; }

/* live teaser */
.live-in { display: grid; grid-template-columns: auto minmax(0, 1fr) minmax(0, 1.3fr); align-items: baseline; gap: 16px 40px; padding-top: 36px; padding-bottom: 36px; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.live-tag { font-size: 12px; color: var(--mute); }
.live .body { max-width: 52ch; }

/* final */
.final { padding: clamp(120px, 14vw, 200px) 0 clamp(120px, 14vw, 200px); background: radial-gradient(ellipse 50% 45% at 50% 55%, rgba(255, 77, 28, 0.07), transparent 70%); }
.final-in { display: flex; flex-direction: column; align-items: center; text-align: center; gap: 24px; }
.final-h { max-width: 14ch; }
.final .lede { max-width: 40ch; }

/* footer */
.footer { border-top: 1px solid var(--line); padding: 28px 0; }
.foot-in { display: flex; align-items: center; gap: 22px; flex-wrap: wrap; font-size: 13px; color: var(--mute); }
.foot-links { margin-left: auto; display: flex; gap: 22px; }
.foot-links a { color: var(--mute); text-decoration: none; }
.foot-links a:hover { color: var(--ink); }

/* reveal */
.reveal { opacity: 0; transform: translateY(20px); transition: opacity 0.8s var(--ease), transform 0.8s var(--ease); }
.reveal.in { opacity: 1; transform: none; }
.reveal.d1 { transition-delay: 0.08s; } .reveal.d2 { transition-delay: 0.16s; } .reveal.d3 { transition-delay: 0.24s; }

/* ---------- narrow: hero, then the replay pinned on top while steps scroll under it ---------- */
@media (max-width: 899px) {
  :root { --nav-h: 56px; }
  .wrap, .nav-in, .story { padding: 0 16px; }
  .nav-links { display: none; }
  .nav-in { justify-content: space-between; }
  .story { grid-template-columns: minmax(0, 1fr); }
  .story-copy { display: contents; }
  .hero { order: 0; min-height: auto; padding: 44px 0 32px; }
  .stage { order: 1; grid-column: 1; grid-row: auto; height: auto; z-index: 2; background: var(--bg); padding: 8px 0 10px; }
  .step { order: 2; min-height: 78dvh; justify-content: flex-end; padding: 32px 0 14vh; }
  .step:last-child { min-height: 90dvh; }
  .stage-canvas { height: 34dvh; }
  .stage-log { height: 88px; }
  .stage-cap { display: none; }
  .stage-layers { gap: 10px; font-size: 11px; }
  .fight-line { height: 150px; }
  .fight-tape { grid-template-columns: minmax(0, 1fr); }
  .tape-row { grid-template-columns: 3ch 1fr 72px 1fr 3ch; gap: 8px; }
  .method-grid { grid-template-columns: minmax(0, 1fr); }
  .method-h { position: static; }
  .live-in { grid-template-columns: minmax(0, 1fr); }
  .foot-links { margin-left: 0; }
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  .reveal { opacity: 1; transform: none; transition: none; }
  .hero > *, .log-row { animation: none; }
  .tape-row .bar i { transition: none; }
}

