240	  const canvasRef = sRef(null), wrapRef = sRef(null), frameRef = sRef(null), readRef = sRef(null);
241	  const modeRef = sRef(mode);
242	  const tRef = sRef(LOOP_START);
243	  const [playing, setPlaying] = sState(() => !reducedMotion());
244	  const playingRef = sRef(playing);
245	  const [passed, setPassed] = sState(0);
246	  const passedRef = sRef(0);
247	  const redraw = sRef(() => {});
248	
249	  modeRef.current = mode;
250	  playingRef.current = playing;
251	
252	  sEffect(() => {
253	    const s = S.current, cv = canvasRef.current, ctx = cv.getContext('2d');
254	    let W = 0, H = 0, dpr = 1, raf = 0, last = 0, hold = 0, visible = true;
255	    if (!playingRef.current) tRef.current = s.events[2].si + 2;
256	    const paint = () => {
257	      const call = drawStage(ctx, s, W, H, tRef.current, modeRef.current, dpr);
258	      const f = Math.round(s.start + tRef.current * s.step);
259	      if (frameRef.current) frameRef.current.textContent = f;
260	      if (readRef.current) readRef.current.textContent = call && modeRef.current === 'strike'
261	        ? `${call.fam}  /  ${call.t}` : '';
262	      const n = s.events.filter((e) => e.si <= tRef.current).length;
263	      if (n !== passedRef.current) { passedRef.current = n; setPassed(n); }
264	    };
265	    redraw.current = paint;
266	    const size = () => {
267	      const r = cv.getBoundingClientRect();
268	      dpr = Math.min(2, window.devicePixelRatio || 1);
269	      W = cv.width = Math.round(r.width * dpr); H = cv.height = Math.round(r.height * dpr);
270	      paint();
271	    };
