1	// app/stage.jsx — replays window.EXCHANGE (real keypoints + verified strikes) on a canvas.
2	// `mode` peels the pipeline apart: detect → corners → strike → log; `full` shows everything.
3	const { useEffect: sEffect, useRef: sRef, useState: sState } = React;
4	
5	const BONES = [[5, 7], [7, 9], [6, 8], [8, 10], [5, 6], [5, 11], [6, 12], [11, 12], [11, 13], [13, 15], [12, 14], [14, 16]];
6	const HEAD = [0, 1, 2, 3, 4];
7	const MIN_CONF = 30;            // keypoint conf * 100 below this is a guess, not a joint
8	const HZ = 25;                  // samples per second (the strike model's rate)
9	const WINDOW = 15;              // ±15 samples = the model's 31-sample, 1.2 s window
10	const CORNER = ['#ef4444', '#4f93ea'];
11	const CORNER_NAME = ['Red', 'Blue'];
12	const INK = '242,241,238';
13	const STRIP_H = 34;             // css px reserved for the sample strip
14	const LOOP_START = 10;          // skip the opening close-up, where the broadcast crops red's legs
15	const LOOP_HOLD = 0.7;          // seconds to rest on the last frame before restarting
16	const LOOP_FADE = 0.4;          // seconds for each half of the fade through black at the restart
17	
18	const STRIKE_LABEL = {
19	  jab: 'Jab', cross: 'Cross', left_hook: 'Left hook', right_hook: 'Right hook',
20	  left_uppercut: 'Left uppercut', right_uppercut: 'Right uppercut',
21	  low_kick: 'Low kick', calf_kick: 'Calf kick', middle_kick: 'Middle kick', high_kick: 'Head kick', clinch_knee: 'Knee',
22	};
23	const familyOf = (a) => (a.includes('hook') ? 'hook' : a.includes('uppercut') ? 'uppercut' : a.endsWith('kick') ? 'kick' : a.endsWith('knee') ? 'knee' : a);
24	
25	/* ---------- data prep ---------- */
26	function parseRow(r) {
27	  if (!r) return null;
28	  const kp = [];
29	  for (let j = 0; j < 17; j++) kp.push({ x: r[5 + j * 3], y: r[6 + j * 3], c: r[7 + j * 3] });
30	  return { box: r.slice(0, 4), conf: r[4], kp };
31	}
32	function holdGaps(arr) {
33	  const out = arr.slice();
34	  for (let i = 1; i < out.length; i++) if (!out[i]) out[i] = out[i - 1];
35	  for (let i = out.length - 2; i >= 0; i--) if (!out[i]) out[i] = out[i + 1];
36	  return out;
37	}
38	const mean = (pts) => pts.length ? { x: pts.reduce((s, p) => s + p.x, 0) / pts.length, y: pts.reduce((s, p) => s + p.y, 0) / pts.length } : null;
39	const conf = (kp, idx) => idx.map((j) => kp[j]).filter((p) => p.c >= MIN_CONF);
40	const dist = (a, b) => Math.hypot(a.x - b.x, a.y - b.y);
41	
42	// the broadcast camera zooms and pans; a smoothed union box keeps both fighters framed
43	function buildCam(a, b) {
44	  const raw = a.map((p, i) => {
45	    const q = b[i];
46	    const x1 = Math.min(p.box[0], q.box[0]), y1 = Math.min(p.box[1], q.box[1]);
47	    const x2 = Math.max(p.box[2], q.box[2]), y2 = Math.max(p.box[3], q.box[3]);
48	    return [(x1 + x2) / 2, (y1 + y2) / 2, x2 - x1, y2 - y1];
49	  });
50	  const R = 10;
51	  return raw.map((_, i) => {
52	    const acc = [0, 0, 0, 0]; let ws = 0;
53	    for (let k = -R; k <= R; k++) {
54	      const s = raw[Math.min(raw.length - 1, Math.max(0, i + k))];
55	      const w = Math.exp(-(k * k) / (2 * (R / 2) ** 2));
56	      for (let d = 0; d < 4; d++) acc[d] += s[d] * w;
57	      ws += w;
58	    }
59	    return acc.map((v) => v / ws);
60	  });
61	}
62	
63	// which limb threw it, and where it was aimed, read from the pose at the strike frame
64	function strikeGeometry(e, tracks) {
65	  const i = Math.round(e.si);
66	  const me = tracks[e.c][i].kp, op = tracks[1 - e.c][i].kp;
67	  const opHead = mean(conf(op, HEAD)) || mean(conf(op, [5, 6]));
68	  const opBody = mean(conf(op, [5, 6, 11, 12]));
69	  const opLeg = mean(conf(op, [13, 14])) || opBody;
70	  const target = e.t === 'head' ? opHead : e.t === 'leg' ? opLeg : opBody;
71	  const fam = familyOf(e.a);
72	  let chain;
73	  if (fam === 'kick' || fam === 'knee') {
74	    const hip = mean(conf(me, [11, 12])) || mean(conf(me, [5, 6]));
75	    const end = fam === 'kick' ? [15, 16] : [13, 14];
76	    const pick = end.map((j) => me[j]).map((p, k) => ({ p, k })).filter((o) => o.p.c >= MIN_CONF)
77	      .sort((u, v) => (hip ? dist(v.p, hip) - dist(u.p, hip) : 0))[0];
78	    const left = pick ? pick.k === 0 : true;
79	    chain = fam === 'kick' ? (left ? [11, 13, 15] : [12, 14, 16]) : (left ? [11, 13] : [12, 14]);
80	  } else if (e.a.startsWith('left_')) chain = [5, 7, 9];
81	  else if (e.a.startsWith('right_')) chain = [6, 8, 10];
82	  else {
83	    const aim = target || opHead;
84	    const d9 = me[9].c >= MIN_CONF && aim ? dist(me[9], aim) : Infinity;
85	    const d10 = me[10].c >= MIN_CONF && aim ? dist(me[10], aim) : Infinity;
86	    chain = d9 <= d10 ? [5, 7, 9] : [6, 8, 10];
87	  }
88	  return { chain, fam, targetKind: e.t };
89	}
90	
91	function prepExchange(E) {
92	  const tracks = [holdGaps(E.red.map(parseRow)), holdGaps(E.blue.map(parseRow))];
93	  const events = E.events.map((ev) => {
94	    const e = { f: ev.f, c: ev.c, a: ev.a, t: ev.t, si: (ev.f - E.start) / E.step };
95	    return Object.assign(e, strikeGeometry(e, tracks));
96	  });
97	  return { n: tracks[0].length, start: E.start, step: E.step, tracks, cam: buildCam(tracks[0], tracks[1]), events };
98	}
99	
100	/* ---------- drawing ---------- */
101	const lerp = (a, b, t) => a + (b - a) * t;
102	function poseAt(track, t) {
103	  const i0 = Math.floor(t), i1 = Math.min(track.length - 1, i0 + 1), a = t - i0;
104	  const p = track[i0], q = track[i1];
105	  return {
106	    box: p.box.map((v, k) => lerp(v, q.box[k], a)),
107	    conf: lerp(p.conf, q.conf, a),
108	    kp: p.kp.map((k0, j) => ({ x: lerp(k0.x, q.kp[j].x, a), y: lerp(k0.y, q.kp[j].y, a), c: Math.min(k0.c, q.kp[j].c) })),
109	  };
110	}
111	function bracket(ctx, x1, y1, x2, y2, len) {
112	  ctx.beginPath();
113	  ctx.moveTo(x1, y1 + len); ctx.lineTo(x1, y1); ctx.lineTo(x1 + len, y1);
114	  ctx.moveTo(x2 - len, y1); ctx.lineTo(x2, y1); ctx.lineTo(x2, y1 + len);
115	  ctx.moveTo(x2, y2 - len); ctx.lineTo(x2, y2); ctx.lineTo(x2 - len, y2);
116	  ctx.moveTo(x1 + len, y2); ctx.lineTo(x1, y2); ctx.lineTo(x1, y2 - len);
117	  ctx.stroke();
118	}
119	
120	function drawStage(ctx, S, W, H, t, mode, dpr) {
121	  ctx.clearRect(0, 0, W, H);
122	  const coloured = mode !== 'detect';
123	  const strikes = mode === 'full' || mode === 'strike' || mode === 'log';
124	  const plotH = H - STRIP_H * dpr;
125	  const i0 = Math.floor(t), a = t - i0, c0 = S.cam[i0], c1 = S.cam[Math.min(S.n - 1, i0 + 1)];
126	  const cam = c0.map((v, k) => lerp(v, c1[k], a));
127	  const sc = Math.min((W * 0.84) / cam[2], (plotH * 0.8) / cam[3]);
128	  const P = (p) => [W / 2 + (p.x - cam[0]) * sc, plotH / 2 + (p.y - cam[1]) * sc];
129	  const font = (px, w = 500) => `${w} ${px * dpr}px "JetBrains Mono", ui-monospace, monospace`;
130	  const poses = S.tracks.map((tr) => poseAt(tr, t));
131	
132	  poses.forEach((pose, c) => {
133	    const col = coloured ? CORNER[c] : `rgba(${INK},.62)`;
134	    const kp = pose.kp;
135	    // tracking box, as corner brackets
136	    const [bx1, by1] = P({ x: pose.box[0], y: pose.box[1] });
137	    const [bx2, by2] = P({ x: pose.box[2], y: pose.box[3] });
138	    const x1 = Math.max(2 * dpr, bx1), y1 = Math.max(18 * dpr, by1), x2 = Math.min(W - 2 * dpr, bx2), y2 = Math.min(plotH - 4 * dpr, by2);
139	    ctx.lineWidth = 1.5 * dpr; ctx.strokeStyle = col; ctx.globalAlpha = coloured ? 0.75 : 1;
140	    bracket(ctx, x1, y1, x2, y2, Math.min(x2 - x1, y2 - y1) * 0.12);
141	    ctx.globalAlpha = 1;
142	    ctx.font = font(11); ctx.fillStyle = col; ctx.textBaseline = 'bottom';
143	    const tag = (coloured ? CORNER_NAME[c].toUpperCase() : 'PERSON') + '  ' + (pose.conf / 100).toFixed(2);
144	    ctx.fillText(tag, x1, y1 - 5 * dpr);
145	
146	    // bones
147	    ctx.lineCap = 'round'; ctx.lineJoin = 'round';
148	    ctx.lineWidth = 2.4 * dpr; ctx.strokeStyle = coloured ? col : `rgba(${INK},.8)`;
149	    ctx.beginPath();
150	    BONES.forEach(([u, v]) => {
151	      if (kp[u].c < MIN_CONF || kp[v].c < MIN_CONF) return;
152	      const p = P(kp[u]), q = P(kp[v]);
153	      ctx.moveTo(p[0], p[1]); ctx.lineTo(q[0], q[1]);
154	    });
155	    ctx.stroke();
156	
157	    // head
158	    const head = mean(conf(kp, HEAD));
159	    if (head) {
160	      const sh = kp[5].c >= MIN_CONF && kp[6].c >= MIN_CONF ? dist(kp[5], kp[6]) * sc : 40 * dpr;
161	      const [hx, hy] = P(head);
162	      ctx.beginPath(); ctx.arc(hx, hy, Math.max(6 * dpr, Math.min(34 * dpr, sh * 0.3)), 0, Math.PI * 2); ctx.stroke();
163	    }
164	
165	    // joints; the detect layer shows all 17 with their confidence
166	    kp.forEach((p, j) => {
167	      if (!coloured) {
168	        const [x, y] = P(p);
169	        if (p.c >= MIN_CONF) { ctx.fillStyle = `rgba(${INK},${0.35 + (p.c / 100) * 0.65})`; ctx.beginPath(); ctx.arc(x, y, 3.2 * dpr, 0, Math.PI * 2); ctx.fill(); }
170	        else if (x > 0 && x < W && y > 0 && y < plotH) { ctx.lineWidth = 1 * dpr; ctx.strokeStyle = `rgba(${INK},.28)`; ctx.beginPath(); ctx.arc(x, y, 3.2 * dpr, 0, Math.PI * 2); ctx.stroke(); }
171	      } else if (j >= 5 && p.c >= MIN_CONF) {
172	        const [x, y] = P(p);
173	        ctx.fillStyle = '#0f1012'; ctx.beginPath(); ctx.arc(x, y, 2.6 * dpr, 0, Math.PI * 2); ctx.fill();
174	        ctx.lineWidth = 1.4 * dpr; ctx.strokeStyle = col; ctx.stroke();
175	      }
176	    });
177	  });
178	
179	  // strikes: flash the limb that threw it and ring the target
180	  let callout = null;
181	  if (strikes) {
182	    S.events.forEach((e) => {
183	      const ph = t - e.si;
184	      if (ph < -3 || ph > 14) return;
185	      const k = ph < 0 ? (ph + 3) / 3 : 1 - ph / 14;
186	      const kp = poses[e.c].kp;
187	      const pts = e.chain.map((j) => kp[j]).filter((p) => p.c >= MIN_CONF).map(P);
188	      if (pts.length < 2) return;
189	      ctx.globalAlpha = k; ctx.strokeStyle = CORNER[e.c]; ctx.lineWidth = 6 * dpr;
190	      ctx.beginPath(); pts.forEach((p, i) => (i ? ctx.lineTo(p[0], p[1]) : ctx.moveTo(p[0], p[1]))); ctx.stroke();
191	      const end = pts[pts.length - 1];
192	      ctx.lineWidth = 1.6 * dpr;
193	      ctx.beginPath(); ctx.arc(end[0], end[1], (9 + 10 * (1 - k)) * dpr, 0, Math.PI * 2); ctx.stroke();
194	      ctx.font = font(11, 600); ctx.fillStyle = CORNER[e.c]; ctx.textBaseline = 'middle';
195	      ctx.fillText((STRIKE_LABEL[e.a] || e.a).toUpperCase(), end[0] + 16 * dpr, end[1] - 14 * dpr);
196	      ctx.globalAlpha = 1;
197	      if (Math.abs(ph) <= WINDOW) callout = e;
198	    });
199	  }
200	
201	  // 1.2 s trail of the striking hand or foot, as the strike model reads it
202	  if (mode === 'strike') {
203	    const e = S.events.reduce((best, ev) => (Math.abs(t - ev.si) < Math.abs(t - (best ? best.si : Infinity)) ? ev : best), null);
204	    if (e && Math.abs(t - e.si) <= WINDOW) {
205	      const j = e.chain[e.chain.length - 1];
206	      const from = Math.max(0, Math.ceil(e.si - WINDOW)), to = Math.min(t, e.si + WINDOW);
207	      ctx.lineWidth = 1.5 * dpr;
208	      for (let i = from; i < to; i++) {
209	        const p = S.tracks[e.c][i].kp[j], q = S.tracks[e.c][Math.min(S.n - 1, i + 1)].kp[j];
210	        if (p.c < MIN_CONF || q.c < MIN_CONF) continue;
211	        const u = P(p), v = P(q);
212	        ctx.strokeStyle = CORNER[e.c]; ctx.globalAlpha = 0.25 + 0.6 * ((i - from) / (2 * WINDOW));
213	        ctx.beginPath(); ctx.moveTo(u[0], u[1]); ctx.lineTo(v[0], v[1]); ctx.stroke();
214	        ctx.beginPath(); ctx.arc(u[0], u[1], 1.8 * dpr, 0, Math.PI * 2); ctx.fillStyle = CORNER[e.c]; ctx.fill();
215	      }
216	      ctx.globalAlpha = 1;
217	    }
218	  }
219	
220	  // sample strip: one tick per pose sample, playhead, strike marks, model window
221	  const xL = 14 * dpr, xR = W - 14 * dpr, base = H - 12 * dpr;
222	  const X = (s) => xL + (s / (S.n - 1)) * (xR - xL);
223	  ctx.fillStyle = `rgba(${INK},.16)`;
