225	  if (mode === 'strike') {
226	    const w0 = X(Math.max(0, t - WINDOW)), w1 = X(Math.min(S.n - 1, t + WINDOW));
227	    ctx.fillStyle = `rgba(${INK},.09)`; ctx.fillRect(w0, base - 16 * dpr, w1 - w0, 16 * dpr);
228	    ctx.font = font(10.5); ctx.fillStyle = `rgba(${INK},.7)`; ctx.textBaseline = 'bottom';
229	    ctx.fillText('1.2 s WINDOW  31 POSES', Math.min(w0, xR - 150 * dpr), base - 20 * dpr);
230	  }
231	  if (strikes) S.events.forEach((e) => { ctx.fillStyle = CORNER[e.c]; ctx.fillRect(X(e.si) - 2.5 * dpr, base - 14 * dpr, 5 * dpr, 5 * dpr); });
232	  ctx.fillStyle = `rgb(${INK})`; ctx.fillRect(X(t) - 0.75 * dpr, base - 18 * dpr, 1.5 * dpr, 18 * dpr);
233	  return callout;
234	}
