/* ---------- drawing ---------- */
const lerp = (a, b, t) => a + (b - a) * t;
function poseAt(track, t) {
  const i0 = Math.floor(t), i1 = Math.min(track.length - 1, i0 + 1), a = t - i0;
  const p = track[i0], q = track[i1];
  return {
