  const poses = S.tracks.map((tr) => poseAt(tr, t));

  poses.forEach((pose, c) => {
    const col = coloured ? CORNER[c] : `rgba(${INK},.62)`;
    const kp = pose.kp;
    // tracking box, as corner brackets
    const [bx1, by1] = P({ x: pose.box[0], y: pose.box[1] });
    const [bx2, by2] = P({ x: pose.box[2], y: pose.box[3] });
    const x1 = Math.max(2 * dpr, bx1), y1 = Math.max(18 * dpr, by1), x2 = Math.min(W - 2 * dpr, bx2), y2 = Math.min(plotH - 4 * dpr, by2);
