      ctx.font = font(11, 600); ctx.fillStyle = CORNER[e.c]; ctx.textBaseline = 'middle';
      ctx.fillText((STRIKE_LABEL[e.a] || e.a).toUpperCase(), end[0] + 16 * dpr, end[1] - 14 * dpr);
      ctx.globalAlpha = 1;
      if (Math.abs(ph) <= WINDOW) callout = e;
