  }

  // 1.2 s trail of the striking hand or foot, as the strike model reads it
  if (mode === 'strike') {
    const e = S.events.reduce((best, ev) => (Math.abs(t - ev.si) < Math.abs(t - (best ? best.si : Infinity)) ? ev : best), null);
    if (e && Math.abs(t - e.si) <= WINDOW) {
