import re, glob, collections
files = glob.glob('src/**/*.tsx', recursive=True) + glob.glob('src/**/*.ts', recursive=True)
stats = collections.Counter()
SEG = {('src/components/trainingData/EventTable.tsx', 81), ('src/components/trainingData/EventTable.tsx', 89),
       ('src/components/accuracy/AnnotatedEvents.tsx', 263), ('src/components/accuracy/FightLedger.tsx', 96)}
KEEP999 = {('src/components/VideoControls.tsx', 93)}
for p in files:
    lines = open(p).read().split('\n')
    out = []
    for n, line in enumerate(lines, 1):
        orig = line
        # weights: Archivo runs heavier than Manrope, so step every weight down one notch
        def w(m):
            v = int(m.group(1)); stats[f'weight {v}'] += 1
            return 'fontWeight: ' + str({800: 700, 700: 600, 600: 500}.get(v, v))
