  const color = known ? PURPOSE_COLORS[known] : '#64748b';
  const label = known ? PURPOSE_LABELS[known] : purpose;
  const icon = known ? PURPOSE_ICONS[known] : 'help';
  const s = SIZES[size];

  return (
    <span
      title={`Purpose: ${label}`}
      style={{
        display: 'inline-flex',
        alignItems: 'center',
        gap: s.gap,
        flexShrink: 0,
        fontSize: s.font,
        fontWeight: 700,
        letterSpacing: '0.06em',
        textTransform: 'uppercase',
        whiteSpace: 'nowrap',
        padding: s.pad,
        borderRadius: s.radius,
        color,
        background: `color-mix(in srgb, ${color} 16%, transparent)`,
        border: `1px solid color-mix(in srgb, ${color} 36%, transparent)`,
      }}
    >
      <span className="material-symbols-outlined" style={{ fontSize: s.icon }}>
        {icon}
      </span>
      {label}
    </span>
  );
}

