=================== LiveFeed
import { useState, useEffect, useRef, useMemo } from 'react';
import type { Event } from '../../types/Event';
import { categoryForAction, colorForAction, iconForAction } from '../../components/annotate/taxonomy';
import { describeEvent, type DescribeRound } from '../../utils/describeEvent';
import { isFrameSwapped, type CornerSwapSpan } from '../../utils/cornerSwap';

interface LiveFeedProps {
  events: Event[];
  currentFrame: number;
  fps: number;
  onSeek: (time: number) => void;
  redName: string;
  blueName: string;
  redFighterId?: number | null;
  rounds?: DescribeRound[];
  cornerSwapSpans?: CornerSwapSpan[];
}

type Filter = 'all' | 'strike' | 'state' | 'grapple';

const FILTERS: { key: Filter; label: string }[] = [
  { key: 'all',    label: 'All' },
  { key: 'strike', label: 'Strikes' },
  { key: 'state',  label: 'Fight State' },
  { key: 'grapple',label: 'Grapple' },
];

function matchFilter(cat: string, filter: Filter): boolean {
  if (filter === 'all') return true;
  if (filter === 'grapple') return cat === 'grapple' || cat === 'event';
  if (filter === 'state') return cat === 'state' || cat === 'round';
  return cat === filter;
}

function fmtFrame(frame: number, fps: number): string {
  const secs = Math.max(0, Math.floor((frame - 1) / fps));
  const m = Math.floor(secs / 60);
  const s = secs % 60;
  return `${m}:${String(s).padStart(2, '0')}`;
}

export default function LiveFeed({
  events, currentFrame, fps, onSeek, redName, blueName, redFighterId, rounds, cornerSwapSpans,
}: LiveFeedProps) {
  const [filter, setFilter] = useState<Filter>('all');
  const scrollRef = useRef<HTMLDivElement>(null);

  const enriched = useMemo(() => events.map(e => ({
    ...e,
    cat: categoryForAction(e.action),
    tc: fmtFrame(e.frame, fps),
    text: describeEvent(e, {
      redName, blueName, redFighterId, rounds,
      swapped: isFrameSwapped(e.frame, cornerSwapSpans ?? []),
    }),
  })), [events, fps, redName, blueName, redFighterId, rounds, cornerSwapSpans]);

  const visible = useMemo(() =>
    enriched.filter(e => e.frame <= currentFrame && matchFilter(e.cat, filter)),
    [enriched, currentFrame, filter],
  );

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [visible.length]);

  return (
    <div className="glass" style={{ display: 'flex', flexDirection: 'column', height: '100%', overflow: 'hidden' }}>
      {/* Header */}
      <div style={{ padding: '14px 16px 10px', display: 'flex', flexDirection: 'column', gap: 11, borderBottom: '1px solid var(--border-subtle)', flexShrink: 0 }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
          <span style={{ width: 8, height: 8, borderRadius: '50%', background: 'var(--f-red)', animation: 'pulse-ring 1.4s infinite', flexShrink: 0 }} />
          <span className="label" style={{ color: 'rgba(255,255,255,0.55)' }}>Live Play-by-Play</span>
          <span style={{ marginLeft: 'auto', fontSize: 11, color: 'var(--text-disabled)', fontWeight: 500 }}>
            {visible.length} events
          </span>
        </div>
        <div style={{ display: 'flex', gap: 6 }}>
          {FILTERS.map(f => (
            <button key={f.key} className={'pill' + (filter === f.key ? ' active' : '')} onClick={() => setFilter(f.key)}>
              {f.label}
            </button>
          ))}
        </div>
      </div>

      {/* Event list */}
      <div ref={scrollRef} style={{ flex: 1, overflowY: 'auto', padding: 8, display: 'flex', flexDirection: 'column', gap: 9, overscrollBehavior: 'contain' }}>
        {visible.length === 0 ? (
          <div style={{ margin: 'auto', textAlign: 'center', color: 'var(--text-disabled)', fontSize: 13, padding: 30 }}>
            <span className="material-symbols-outlined" style={{ fontSize: 34, opacity: 0.3, display: 'block', marginBottom: 8 }}>sensors</span>
            Waiting for events…
          </div>
        ) : visible.map(e => {
          const c = colorForAction(e.action);
          const icon = iconForAction(e.action);
          return (
            <button
              key={e.id}
              onClick={() => onSeek((e.frame - 1) / fps)}
              style={{ display: 'flex', gap: 11, alignItems: 'flex-start', textAlign: 'left', padding: '11px 13px', borderRadius: 8, border: `1px solid var(--border-subtle)`, background: 'var(--surface-inner)', borderLeft: `3px solid ${c}`, cursor: 'pointer', animation: 'feed-in .35s ease-out', width: '100%' }}
            >
              <span style={{ width: 28, height: 28, flexShrink: 0, borderRadius: 6, display: 'grid', placeItems: 'center', background: `color-mix(in srgb, ${c} 14%, transparent)`, border: `1px solid color-mix(in srgb, ${c} 30%, transparent)` }}>
                <span className="material-symbols-outlined" style={{ fontSize: 16, color: c }}>{icon}</span>
              </span>
              <span style={{ minWidth: 0, flex: 1 }}>
                <span style={{ display: 'block', fontSize: 13, fontWeight: 500, color: 'var(--text-primary)', lineHeight: 1.25, marginBottom: 2 }}>
                  {e.text}
                </span>
                <span style={{ display: 'flex', alignItems: 'center', gap: 8, fontSize: 11, color: 'var(--text-disabled)' }}>
                  <span style={{ fontVariantNumeric: 'tabular-nums', color: 'var(--text-muted)', fontWeight: 600 }}>{e.tc}</span>
                  <span style={{ marginLeft: 'auto', opacity: 0.7 }}>#{e.frame}</span>
                </span>
              </span>
            </button>
          );
        })}
      </div>
    </div>
  );
}
=================== FightReport
import { useState } from 'react';
import { useWindowWidth } from '../../hooks/useWindowWidth';
import ScopeToggle from './ScopeToggle';
import type { Scope } from './ScopeToggle';
import FighterColumn from './FighterColumn';
import SummaryTiles from './SummaryTiles';
import HeadToHead from './HeadToHead';
import Momentum from './Momentum';
import type { FighterProfile, FighterStats } from '../../mocks/fightMock';
import type { Event } from '../../types/Event';
import type { Round } from '../../types/Round';
import { deriveStatsForRange } from '../../utils/liveStats';

interface FightReportProps {
  currentFrame: number;
  events: Event[];
  fps: number;
  rounds: Round[];
  fighters: { red: FighterProfile; blue: FighterProfile };
  redFighterId?: number | null;
  time: number;
  duration: number;
  r1EndSeconds: number;
}

/** One real-data sentence in place of the design's hand-written fight
 * narrative — built entirely from the same FighterStats every tile on this
 * page already derives from real events, never a fabricated storyline. */
function summarize(red: FighterStats, blue: FighterStats, redName: string, blueName: string): string {
  if (red.sig[1] + blue.sig[1] === 0) return 'No strikes logged yet for this scope.';
  const clauses: string[] = [];
  if (red.sig[0] !== blue.sig[0]) {
    const [wName, wSig, lSig] = red.sig[0] > blue.sig[0] ? [redName, red.sig[0], blue.sig[0]] : [blueName, blue.sig[0], red.sig[0]];
    clauses.push(`${wName} out-landed the opponent ${wSig}–${lSig} in significant strikes`);
  } else {
    clauses.push(`${redName} and ${blueName} landed an even ${red.sig[0]} significant strikes apiece`);
  }
  if (red.ctrl + blue.ctrl > 0) {
    const [cName, cSec] = red.ctrl >= blue.ctrl ? [redName, red.ctrl] : [blueName, blue.ctrl];
    clauses.push(`${cName} controlled ${Math.round(cSec / 60)} min of mat time`);
  }
  if (red.kd + blue.kd > 0) {
    const kName = red.kd > blue.kd ? redName : blueName;
    clauses.push(`${kName} scored the only knockdown`);
  }
  return clauses.join('. ') + '.';
}

export default function FightReport({ currentFrame, events, fps, rounds, fighters, redFighterId, time, duration, r1EndSeconds }: FightReportProps) {
  const [scope, setScope] = useState<Scope>('fight');
  const width = useWindowWidth();
  const narrow = width < 1100;

  let st: { red: FighterStats; blue: FighterStats };
  let scopeLabel: string;
  if (scope === 'live') {
    st = deriveStatsForRange(events, 0, currentFrame, fps, redFighterId);
    scopeLabel = 'the fight so far';
  } else if (scope === 'fight') {
    st = deriveStatsForRange(events, 0, Infinity, fps, redFighterId);
    scopeLabel = 'the fight';
  } else {
    const round = rounds.find(r => r.round_number === scope);
    st = round
      ? deriveStatsForRange(events, round.start_frame, round.end_frame, fps, redFighterId)
      : deriveStatsForRange(events, 0, Infinity, fps, redFighterId);
    scopeLabel = `round ${scope}`;
  }

  const redName = fighters.red.name, blueName = fighters.blue.name;

  return (
    <section style={{ marginTop: 56 }}>
      <div style={{ display: 'flex', alignItems: 'flex-end', gap: 20, flexWrap: 'wrap', marginBottom: 22 }}>
        <div style={{ minWidth: 0 }}>
          <span className="eyebrow">Report</span>
          <h2 className="font-display" style={{ fontSize: 'clamp(28px, 3.4vw, 40px)', lineHeight: 1, margin: '10px 0 0', color: 'var(--text-primary)' }}>
            The whole fight, broken down.
          </h2>
          <p style={{ margin: '10px 0 0', fontSize: 14, fontWeight: 500, color: 'var(--text-muted)', maxWidth: '52ch' }}>
            {summarize(st.red, st.blue, redName, blueName)}
          </p>
        </div>
        <div style={{ marginLeft: 'auto' }}>
          <ScopeToggle scope={scope} setScope={setScope} rounds={rounds} />
        </div>
      </div>

      <div style={{ marginBottom: 12 }}>
        <SummaryTiles red={st.red} blue={st.blue} redName={redName} blueName={blueName} scopeLabel={scopeLabel} />
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: narrow ? 'minmax(0,1fr)' : 'minmax(0,1fr) minmax(0,1fr)', gap: 12 }}>
        <HeadToHead red={st.red} blue={st.blue} redName={redName} blueName={blueName} />
        <div style={{ display: 'grid', gap: 12 }}>
          <FighterColumn f={fighters.red} s={st.red} />
          <FighterColumn f={fighters.blue} s={st.blue} />
        </div>
      </div>

      <div className="glass" style={{ marginTop: 12, padding: '22px 24px' }}>
        <div style={{ display: 'flex', alignItems: 'baseline', gap: 16, flexWrap: 'wrap', marginBottom: 18 }}>
          <h3 style={{ margin: 0, fontSize: 22, fontWeight: 700, letterSpacing: '-0.02em', color: 'var(--text-primary)' }}>Momentum.</h3>
          <span style={{ fontSize: 13, fontWeight: 500, color: 'var(--text-muted)' }}>Significant strikes landed per 30 seconds</span>
          <span style={{ display: 'flex', gap: 16, fontSize: 11.5, fontWeight: 600, marginLeft: 'auto' }}>
            <span style={{ color: 'var(--f-red)' }}>{redName}</span>
            <span style={{ color: 'var(--f-blue)' }}>{blueName}</span>
          </span>
        </div>
        <Momentum time={time} duration={duration} r1EndSeconds={r1EndSeconds} events={events} fps={fps} fighters={fighters} redFighterId={redFighterId} bare />
      </div>
    </section>
  );
}
