interface PaceChartProps {
  time: number;
  duration: number;
  r1End: number;
  height?: number;
  redPace: number[];
  bluePace: number[];
}

export default function PaceChart({ time, duration, r1End, height = 150, redPace, bluePace }: PaceChartProps) {
  const W = 900, H = height, padB = 22, padT = 12;
  const n = redPace.length;
  if (n < 2) return null;

  const maxY = Math.max(4, ...redPace, ...bluePace);
  const x = (i: number) => (i / (n - 1)) * W;
  const y = (v: number) => H - padB - (v / maxY) * (H - padB - padT);
  const line = (arr: number[]) =>
    arr.map((v, i) => `${i === 0 ? 'M' : 'L'}${x(i).toFixed(1)},${y(v).toFixed(1)}`).join(' ');
  const area = (arr: number[]) => `${line(arr)} L${W},${H - padB} L0,${H - padB} Z`;
  const r1x = duration > 0 ? (r1End / duration) * W : W / 2;
  const nowx = duration > 0 ? Math.min((time / duration) * W, W) : 0;

  return (
    <svg viewBox={`0 0 ${W} ${H}`} width="100%" height={height} preserveAspectRatio="none" style={{ display: 'block', overflow: 'visible' }}>
      <defs>
        <linearGradient id="pg-red" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor="var(--f-red)" stopOpacity="0.35" />
          <stop offset="100%" stopColor="var(--f-red)" stopOpacity="0" />
        </linearGradient>
        <linearGradient id="pg-blue" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor="var(--f-blue)" stopOpacity="0.35" />
          <stop offset="100%" stopColor="var(--f-blue)" stopOpacity="0" />
        </linearGradient>
      </defs>
      <line x1={r1x} y1={padT - 4} x2={r1x} y2={H - padB} stroke="var(--green-500)" strokeOpacity="0.4" strokeDasharray="4 4" />
      <text x={6} y={padT + 4} fill="var(--text-disabled)" fontSize="10" fontWeight="700">R1</text>
      <text x={r1x + 6} y={padT + 4} fill="var(--text-disabled)" fontSize="10" fontWeight="700">R2</text>
      <path d={area(redPace)} fill="url(#pg-red)" />
      <path d={area(bluePace)} fill="url(#pg-blue)" />
      <path d={line(redPace)} fill="none" stroke="var(--f-red)" strokeWidth="2.5" />
      <path d={line(bluePace)} fill="none" stroke="var(--f-blue)" strokeWidth="2.5" />
      {duration > 0 && (
        <>
          <line x1={nowx} y1={padT - 4} x2={nowx} y2={H - padB} stroke="var(--accent)" strokeWidth="1.5" />
          <circle cx={nowx} cy={padT - 4} r="3" fill="var(--accent)" />
        </>
      )}
      <line x1="0" y1={H - padB} x2={W} y2={H - padB} stroke="rgba(255,255,255,0.08)" />
    </svg>
  );
}
=================== EdgeMeter
export interface EdgeTape {
  label: string;
  r: string | number;
  b: string | number;
  lowerWins?: boolean;
}

function tapeNum(v: string | number): number {
  if (typeof v === 'number') return v;
  const ft = /(\d+)'(\d+)/.exec(v);
  if (ft) return (+ft[1]) * 12 + (+ft[2]);
  const inch = /(\d+)"/.exec(v);
  if (inch) return +inch[1];
  return parseFloat(v) || 0;
}

function tapeDelta(t: EdgeTape) {
  const rn = tapeNum(t.r), bn = tapeNum(t.b);
  const rWin = t.lowerWins ? rn < bn : rn > bn;
  const bWin = t.lowerWins ? bn < rn : bn > rn;
  const diff = Math.abs(rn - bn);
  const unit = t.label === 'Age' ? (diff === 1 ? ' yr' : ' yrs') : '"';
  const winnerColor = rWin ? 'var(--f-red)' : (bWin ? 'var(--f-blue)' : 'var(--text-disabled)');
  return { rWin, bWin, diff, unit, winnerColor };
}

export function EdgeRow({ t }: { t: EdgeTape }) {
  const { rWin, bWin, diff, unit, winnerColor } = tapeDelta(t);
  const lean = Math.min(diff / 8, 1) * 50;
  return (
    <div style={{ marginBottom: 20 }}>
      <div style={{ display: 'grid', gridTemplateColumns: '58px 1fr 58px', alignItems: 'center', gap: 16 }}>
        <span className="font-display" style={{ fontSize: 23, textAlign: 'right', color: rWin ? 'var(--f-red)' : 'var(--text-tertiary)' }}>{t.r}</span>
        <div>
          <div style={{ textAlign: 'center', fontSize: 11, fontWeight: 600, color: 'var(--text-muted)', marginBottom: 7 }}>
            {t.label}
          </div>
          <div style={{ position: 'relative', height: 12 }}>
            <div style={{ position: 'absolute', inset: 0, borderRadius: 6, background: 'var(--surface-inner)', border: '1px solid var(--border-subtle)' }} />
            <div style={{ position: 'absolute', top: 0, bottom: 0, left: '50%', width: 1, background: 'var(--border-glass)' }} />
            {diff > 0 && (
              <div style={{ position: 'absolute', top: 1, bottom: 1, left: rWin ? `${50 - lean}%` : '50%', width: `${lean}%`, borderRadius: 6, background: winnerColor, boxShadow: `0 0 10px ${winnerColor}` }} />
            )}
          </div>
          <div style={{ textAlign: 'center', marginTop: 7, fontSize: 10, fontWeight: 700, letterSpacing: '0.04em', color: winnerColor }}>
            {diff > 0 ? `+${diff}${unit}` : 'EVEN'}
          </div>
        </div>
        <span className="font-display" style={{ fontSize: 23, textAlign: 'left', color: bWin ? 'var(--f-blue)' : 'var(--text-tertiary)' }}>{t.b}</span>
      </div>
    </div>
  );
}
