import { useEffect, useState } from 'react';
import { TOOL_GROUPS, colorForAction, iconForAction, type ToolItem } from './taxonomy';

interface EventPaletteProps {
  selected: boolean;
  onLog: (item: ToolItem, shiftKey?: boolean) => void;
  onFightEnd: () => void;
}

export default function EventPalette({ selected, onLog, onFightEnd }: EventPaletteProps) {
  // Live target preview while Shift is held — logTool() already resolves the
  // correct target from e.shiftKey at log time, this is purely so the
  // button/tooltip shows what's about to be logged before the key is pressed
  // (TODO.md #5).
  const [shiftHeld, setShiftHeld] = useState(false);
  useEffect(() => {
    const onKeyDown = (e: KeyboardEvent) => { if (e.key === 'Shift') setShiftHeld(true); };
    const onKeyUp = (e: KeyboardEvent) => { if (e.key === 'Shift') setShiftHeld(false); };
    const onBlur = () => setShiftHeld(false); // e.g. alt-tab away while holding Shift
    window.addEventListener('keydown', onKeyDown);
    window.addEventListener('keyup', onKeyUp);
    window.addEventListener('blur', onBlur);
    return () => {
      window.removeEventListener('keydown', onKeyDown);
      window.removeEventListener('keyup', onKeyUp);
      window.removeEventListener('blur', onBlur);
    };
  }, []);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
      {TOOL_GROUPS.map(g => (
        <div key={g.group}>
          <div style={{ display: 'flex', alignItems: 'baseline', gap: 8, marginBottom: 9 }}>
            <div className="label" style={{ fontSize: 9.5 }}>{g.group}</div>
            {g.note && <div style={{ fontSize: 10, color: 'var(--text-disabled)', fontWeight: 500 }}>{g.note}</div>}
          </div>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2,1fr)', gap: 8 }}>
            {g.items.map(it => {
              const c = colorForAction(it.action);
              const blocked = it.needsFighter && !selected;
              const previewTarget = it.hasTarget ? (shiftHeld ? 'Body' : 'Head') : null;
              return (
                <button
                  key={it.key}
                  onClick={e => { e.currentTarget.blur(); onLog(it, e.shiftKey); }}
                  title={blocked ? 'Select a fighter first' : previewTarget ? `${it.name} · ${previewTarget} (Shift = body)` : it.name}
                  style={{
                    display: 'flex', alignItems: 'center', gap: 9, padding: '9px 11px', borderRadius: 8,
                    cursor: 'pointer', textAlign: 'left', border: '1px solid var(--border-subtle)',
                    background: 'var(--surface-inner)', borderLeft: `3px solid ${c}`,
                    opacity: blocked ? 0.42 : 1, transition: 'transform .1s,opacity .12s',
                    fontFamily: 'inherit',
                  }}
                >
                  {it.num ? (
                    <span className="punch-num" style={{ color: c, borderColor: `color-mix(in srgb, ${c} 45%, transparent)`, background: `color-mix(in srgb, ${c} 14%, transparent)` }}>{it.num}</span>
                  ) : (
                    <span className="kbd">{it.key.toUpperCase()}</span>
                  )}
                  <span className="material-symbols-outlined" style={{ fontSize: 18, color: c }}>{iconForAction(it.action)}</span>
                  <span style={{ fontSize: 12.5, fontWeight: 500, color: 'var(--text-secondary)', lineHeight: 1.1 }}>
                    {it.name}{previewTarget === 'Body' && <span style={{ color: 'var(--accent)' }}> · Body</span>}
                  </span>
                </button>
              );
            })}
          </div>
        </div>
      ))}

      <div>
        <div className="label" style={{ fontSize: 9.5, marginBottom: 9 }}>Fight result</div>
        <button
          onClick={onFightEnd}
          style={{
            width: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 8,
            padding: '11px 8px', borderRadius: 8, cursor: 'pointer', fontWeight: 600, fontSize: 12.5,
            border: '1px solid color-mix(in srgb, var(--purple-600) 40%, transparent)',
            background: 'color-mix(in srgb, var(--purple-600) 10%, transparent)',
            color: 'var(--text-primary)', fontFamily: 'inherit',
          }}
        >
          <span className="material-symbols-outlined" style={{ fontSize: 18, color: 'var(--purple-600)' }}>sports_score</span>
          End of fight
        </button>
      </div>
    </div>
  );
}
