ok pages/Annotate.tsx 10
20:- **Fight-state marks** (`W`/`F`/`G`) are change points, not spans. The timeline's STATE lane pairs each mark with the next one. In the UI the last mark runs to the end of the timeline, but `ai/eval/labels_db.py` ends it at the end of its round.
23:- **`round`** spans are seeded server-side from `rounds` on first fetch. They show as draggable blocks in the ROUNDS lane, and edge-drag → `onUpdateSpan` → `PUT frame/end_frame`.
28:- **Re-editing** (`isEditingLabels` = `labeling_in_progress && labeled_at !== null`) shows the "Edit labels" title. `needsRoundReview` also checks `labeled_at`, so the unverified-rounds banner doesn't come back during an edit. The "already labeled" screen offers the same **Edit labels** action.
interface SaveStatusProps {
  saving: boolean;
}

export default function SaveStatus({ saving }: SaveStatusProps) {
  return (
    <div style={{
      display: 'inline-flex', alignItems: 'center', gap: 7, padding: '7px 13px', borderRadius: 8,
      border: '1px solid var(--border-glass)', background: 'var(--surface-inner)',
      color: 'var(--text-secondary)', fontSize: 12.5, fontWeight: 600,
    }}>
      <span
        className="material-symbols-outlined"
        style={{ fontSize: 17, color: saving ? 'var(--text-muted)' : 'var(--green-500)', animation: saving ? 'spin 1s linear infinite' : undefined }}
      >
        {saving ? 'sync' : 'cloud_done'}
      </span>
      {saving ? 'Saving…' : 'All changes saved'}
    </div>
  );
}
