          <optgroup key={g.name} label={g.name}>
            {g.items.map((c) => (
              <option key={c.action} value={c.action} style={{ color: '#000' }}>{c.name}</option>
            ))}
          </optgroup>
        ))}
      </select>
      {error && <span style={{ fontSize: 10, fontWeight: 500, color: '#ef4444' }}>{error}</span>}
    </div>
  );
}

function Meta({ k, v, mono, tone }: { k: string; v: React.ReactNode; mono?: boolean; tone?: string }) {
