                  <td colSpan={HEADERS.length - 1} style={{ padding: '9px 10px', borderBottom: '1px solid rgba(255,255,255,0.04)' }}>
                    <StatusBadge status="none" size="sm">Not scorable — no evaluation fixture yet</StatusBadge>
